import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { setStoreAdmin } from '../../features/storeAdminSlice';

const AdminItem = ({ admin, removeAdmin }) => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const [status, setStatus] = useState(admin.account_status);
    const darkMode = useSelector((state) => state.darkMode.mode);

    const handleDelete = async () => {
        removeAdmin(admin.id);

        try {
            const response = await fetch(`https://my-duka-back-end.vercel.app/adminAccountStatus/${admin.id}`, {
                method: 'DELETE',
                headers: {
                    'Content-Type': 'application/json',
                },
            });

            if (response.ok) {
                console.log(`Deleted ${admin.name}`);
            } else {
                console.error('Error deleting admin:', response.statusText);
            }
        } catch (error) {
            console.error('Error deleting admin:', error);
        }
    };

    const handleInactivate = async () => {
        try {
            const response = await fetch(`https://my-duka-back-end.vercel.app/adminAccountStatus/${admin.id}`);
            if (response.ok) {
                const data = await response.json();
                console.log(`Inactivated ${admin.username}`);
                setStatus(data.status);
            } else {
                console.error('Error inactivating merchant:', response.statusText);
            }
        } catch (error) {
            console.error('Error inactivating merchant:', error);
        }
    };

    const handleNavigate = () => {
        dispatch(setStoreAdmin(admin));
        navigate(`/admin/${admin.id}`);
    };

    return (
        <div className={`flex items-center justify-between ${darkMode ? 'bg-dark-background text-text' : 'bg-white text-gray-800'} shadow-md rounded-lg p-4 my-2`}>
            <span className={`font-medium ${darkMode ? 'text-gray-300' : 'text-gray-700'}`}>{`Store ${admin.store_id} [${admin.username}]`}</span>
            <div className="flex space-x-2">
                <button 
                    onClick={handleDelete} 
                    className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600 hover:scale-105 hover:shadow-lg transition duration-300"
                >
                    Delete
                </button>
                <button 
                    onClick={handleInactivate} 
                    className={`px-4 py-2 rounded transition duration-300 ${status === 'Active' ? 'bg-accent1 text-white hover:bg-accent2 scale-105 shadow-lg' : 'bg-gray-500 text-white hover:bg-gray-600 scale-105 shadow-lg'}`}
                >
                    {status}
                </button>
                <button 
                    className="bg-primary text-white px-4 py-2 rounded hover:bg-hover hover:scale-105 hover:shadow-lg transition duration-300" 
                    onClick={handleNavigate}
                >
                    View Store
                </button>
            </div>
        </div>
    );
};

export default AdminItem;
