import React, { useState, useEffect } from "react";
import AdminItem from "../AdminItem/AdminItem";
import Sidebar from "../Sidebar/Sidebar";
import AddAdminForm from "../AddAdminForm/AddAdminForm";
import { useSelector, useDispatch } from "react-redux";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts";
import { showAddStore } from "../../features/showAddStoreSlice";
import { motion } from "framer-motion";

const MerchantDashboard = () => {
  const [admins, setAdmins] = useState([]);
  const user = useSelector((state) => state.user.user);
  const [stores, setStores] = useState([]);
  const showStore = useSelector((state) => state.showAddStore.mode);
  const darkMode = useSelector((state) => state.darkMode.mode);
  const dispatch = useDispatch();

  console.log(darkMode);
  
  const removeAdmin = (id) => {
    setAdmins((prevAdmins) => prevAdmins.filter((admin) => admin.id !== id));
  };

  useEffect(() => {
    fetch("https://my-duka-back-end.vercel.app/getAdmins")
      .then((response) => response.json())
      .then((data) => setAdmins(data))
      .catch((error) => console.error(error));
  }, []);

  useEffect(() => {
    fetch("https://my-duka-back-end.vercel.app/stores")
      .then((res) => res.json())
      .then((data) => setStores(data))
      .catch((error) => console.error(error));
  }, [admins, user]);

  const [isAddAdminFormVisible, setIsAddAdminFormVisible] = useState(false);

  const toggleAddAdminForm = () => {
    setIsAddAdminFormVisible(!isAddAdminFormVisible);
  };

  const [newStore, setNewStore] = useState({
    name: "",
    location: "",
  });

  const handleAddStoreChange = (e) => {
    const { name, value } = e.target;
    setNewStore((prev) => ({ ...prev, [name]: value }));
  };

  const handleAddStoreSubmit = () => {
    fetch(`https://my-duka-back-end.vercel.app/addStore`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(newStore),
    }).then((res) => res.json());

    setNewStore({
      name: "",
      location: "",
    });
    dispatch(showAddStore(false));
  };

  const storeSales = stores.map((store) => {
    const totalSales = store.salesReports.reduce(
      (acc, report) => acc + report.quantity_sold,
      0
    );
    return {
      storeName: store.name,
      sales: totalSales,
    };
  });

  if (user.role === "Merchant") {
    return (
      <div className={`flex ${darkMode ? 'bg-dark-background text-dark.text' : 'bg-background text-text'} min-h-screen`}>
        <Sidebar />
        <div className="flex-1 p-6">
          <div className="flex justify-between items-center mb-4">
            <h1 className={`text-2xl font-semibold ${darkMode?"text-dark-text":"text-text"}`}>Merchant Dashboard - {user.username}</h1>
            <button 
              onClick={toggleAddAdminForm} 
              className="bg-primary text-white px-4 py-2 rounded shadow hover:bg-hover transition duration-300"
            >
              Add Admin
            </button>
          </div>
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            transition={{ duration: 0.5 }}
          >
            {admins.map((admin) => (
              <AdminItem key={admin.id} admin={admin} removeAdmin={removeAdmin} />
            ))}
          </motion.div>
          <div className="mt-6">
            <h3 className="text-lg font-medium">Top 3 Stores by Sales</h3>
            <ResponsiveContainer width="100%" height={400}>
              <BarChart data={storeSales}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="storeName" />
                <YAxis />
                <Tooltip />
                <Legend />
                <Bar dataKey="sales" fill={darkMode ? '#3B82F6' : '#8884d8'} />
              </BarChart>
            </ResponsiveContainer>
          </div>
          {isAddAdminFormVisible && (
            <AddAdminForm onClose={toggleAddAdminForm} />
          )}
          {showStore && (
            <div className="fixed inset-0 flex items-center justify-center bg-gray-800 bg-opacity-50">
              <div className={`rounded shadow p-4 ${darkMode ? 'bg-dark.secondary' : 'bg-white'}`}>
                <h2 className="text-lg font-semibold">Add New Store</h2>
                <input
                  type="text"
                  name="name"
                  value={newStore.name}
                  placeholder="Store Name"
                  onChange={handleAddStoreChange}
                  className={`border ${darkMode ? 'border-dark.border' : 'border-gray-300'} rounded p-2 w-full mt-2`}
                />
                <input
                  type="text"
                  name="location"
                  value={newStore.location}
                  placeholder="Store Location"
                  onChange={handleAddStoreChange}
                  className={`border ${darkMode ? 'border-dark.border' : 'border-gray-300'} rounded p-2 w-full mt-2`}
                />
                <div className="mt-4 flex justify-between">
                  <button 
                    onClick={handleAddStoreSubmit} 
                    className="bg-primary text-white px-4 py-2 rounded shadow hover:bg-hover transition duration-300"
                  >
                    Add
                  </button>
                  <button 
                    onClick={() => dispatch(showAddStore(false))} 
                    className="bg-red-500 text-white px-4 py-2 rounded shadow hover:bg-red-600 transition duration-300"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }
  return null;
};

export default MerchantDashboard;
