// AdminPage.js
import React, { useState, useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";

import { motion } from "framer-motion";
import Sidebar from "./Sidebar/Sidebar";

import {
  approveSupplyRequest,
  declineSupplyRequest,
  markProductAsPaid,
  removeClerk,
  setSupplyRequests,
  setProducts,
  setClerks,
  setReports,
} from "../features/adminSlice";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  BarChart,
  Bar,
  PieChart,
  Pie,
  ResponsiveContainer,
} from "recharts";

import { showAddProduct } from "../features/showAddProductSlice";

const AdminPage = () => {
  const dispatch = useDispatch();

  const [newClerkName, setNewClerkName] = useState("");
  const [newClerkEmail, setNewClerkEmail] = useState("");
  const [showAddClerkPopup, setShowAddClerkPopup] = useState(false);
  const [groupedSalesProduct, setGroupedSalesProduct] = useState({}); // initialize state for grouped sales

  const [editingProductId, setEditingProductId] = useState(null);
  const [editedUnitPrice, setEditedUnitPrice] = useState("");
  const [editedBuyingPrice, setEditedBuyingPrice] = useState("");
  const [sales, setSales] = useState([]);
  const [refreshData, setRefreshData] = useState(false);

  const {
    supplyRequests = [],
    products = [],
    clerks = [],
    reports = {},
  } = useSelector((state) => state.admin);
  const user = useSelector((state) => state.user.user);
  const storeAdmin = useSelector((state) => state.storeAdmin.value);
  const showProduct = useSelector((state) => state.showAddProduct.mode);
  const store_id = user.role === "Admin" ? user.store_id : storeAdmin.store_id;

  // Add these lines here
  const darkMode = useSelector((state) => state.darkMode.mode);

  //  const toggleDarkMode = () => {
  //    setDarkMode(!darkMode);
  //    // You might want to save this preference to localStorage or your state management system
  //  };

  // Insert the new code snippet here

  const [newProduct, setNewProduct] = useState({
    brand_name: "",
    product_name: "",
    number_of_items: "",
    buying_price: "",
    selling_price: "",
  });

  const handleAddProductChange = (e) => {
    const { name, value } = e.target;
    setNewProduct((prev) => ({ ...prev, [name]: value }));
  };

  const handleAddProductSubmit = () => {
    // Implementation for adding the product
    fetch(`https://my-duka-back-end.vercel.app/addProduct/${store_id}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(newProduct),
    })
      .then((res) => res.json())
      .then((data) => setRefreshData((item) => !item));
    // Reset form and close popup
    setNewProduct({
      brand_name: "",
      product_name: "",
      number_of_items: "",
      buying_price: "",
      selling_price: "",
    });
    dispatch(showAddProduct(false));
  };
  // End of new code snippet

  const groupSalesByProduct = (sales) => {
    return sales.reduce((groups, sale) => {
      const { product_name } = sale;

      if (!groups[product_name]) {
        groups[product_name] = [];
      }
      groups[product_name].push(sale);
      return groups;
    }, {});
  };

  const handleEditClick = (product) => {
    setEditingProductId(product.id);
    setEditedUnitPrice(product.selling_price);
    setEditedBuyingPrice(product.buying_price);
  };

  const handleSaveClick = (productId) => {
    // Save the edited values here, probably via an API call
    fetch(`https://my-duka-back-end.vercel.app/updateProduct/${productId}`, {
      method: "PATCH",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        selling_price: editedUnitPrice,
        buying_price: editedBuyingPrice,
      }),
    })
      .then((res) => res.json())
      .then(() => {
        setEditingProductId(null);
        setRefreshData((prev) => !prev); // Refresh the data to reflect changes
      });
  };

  const handleCancelClick = () => {
    setEditingProductId(null);
  };

  useEffect(() => {
    setGroupedSalesProduct(groupSalesByProduct(sales));
  }, [sales]);

  useEffect(() => {
    dispatch(setReports(groupedSalesProduct));
    // eslint-disable-next-line
  }, [groupedSalesProduct]);

  useEffect(() => {
    // Fetch all required data

    const fetchSales = fetch(
      `https://my-duka-back-end.vercel.app/sales/${store_id}`
    ).then((res) => res.json());
    const fetchRequests = fetch(
      `https://my-duka-back-end.vercel.app/requests/${store_id}`
    ).then((res) => res.json());
    const fetchProducts = fetch(
      `https://my-duka-back-end.vercel.app/getProducts/${store_id}`
    ).then((res) => res.json());
    const fetchClerks = fetch(
      `https://my-duka-back-end.vercel.app/getClerk/${store_id}`
    ).then((res) => res.json());

    Promise.all([fetchSales, fetchRequests, fetchProducts, fetchClerks])
      .then(([salesData, requestsData, productsData, clerksData]) => {
        const sortedSales = salesData.sales.sort(
          (a, b) => new Date(a.date) - new Date(b.date)
        );
        // Set local state
        setSales(sortedSales);

        // Dispatch actions after setting state
        dispatch(setSupplyRequests(requestsData));
        dispatch(setProducts(productsData));
        dispatch(setClerks(clerksData));

        dispatch(setReports(groupedSalesProduct)); // Ensure groupedSalesProduct is defined
      })
      .catch((error) => {
        console.error("Error fetching data:", error);
      });
    // eslint-disable-next-line
  }, [refreshData, user]);

  const handleApproveRequest = (id) => {
    fetch(`https://my-duka-back-end.vercel.app/acceptRequests/${id}`)
      .then((res) => res.json())
      .then((data) => console.log(data))
      .then(() => setRefreshData((prev) => !prev));

    dispatch(approveSupplyRequest(id));
  };

  const handleDeclineRequest = (id) => {
    fetch(`https://my-duka-back-end.vercel.app/acceptRequests/${id}`, {
      method: "DELETE",
    })
      .then((res) => res.json())
      .then((data) => console.log(data));

    dispatch(declineSupplyRequest(id));
    setRefreshData((prev) => !prev);
  };

  const handleMarkAsPaid = (id) => {
    fetch(`https://my-duka-back-end.vercel.app/paymentStatus/${id}`)
      .then((res) => res.json())
      .then((data) => console.log(data));

    dispatch(markProductAsPaid(id));
  };

  const handleAddClerk = () => {
    if (newClerkName.trim() && newClerkEmail.trim()) {
      fetch("https://my-duka-back-end.vercel.app/inviteClerk", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ store_id: store_id, email: newClerkEmail }),
      })
        .then((response) => {
          if (!response.ok) {
            throw new Error("Network response was not ok");
          }
          return response.json();
        })
        .then((data) => {
          setNewClerkName("");
          setNewClerkEmail("");
          setShowAddClerkPopup(false);
        })
        .catch((error) => {
          console.error("There was a problem with the fetch operation:", error);
          alert("Failed to add new admin.");
        });
    }
  };

  const handleRemoveClerk = async (id) => {
    try {
      const response = await fetch(
        `https://my-duka-back-end.vercel.app/clerkAccountStatus/${id}`,
        {
          method: "DELETE",
          headers: {
            "Content-Type": "application/json",
          },
        }
      );

      if (response.ok) {
        console.log(`Deleted clerk`);
      } else {
        console.error("Error deleting clerk:", response.statusText);
      }
    } catch (error) {
      console.error("Error deleting clerk:", error);
    }
    dispatch(removeClerk(id));
  };

  const handleInactivateClerk = async (id) => {
    try {
      fetch(
        `https://my-duka-back-end.vercel.app/clerkAccountStatus/${id}`
      ).then((response) => {
        if (response.ok) {
          console.log(`Inactivated clerk`);
          setRefreshData((prev) => !prev);
          // Optionally, you can trigger a refresh or update the state here
          return response.json();
        } else {
          console.error("Error inactivating clerk:", response.statusText);
        }
      });
    } catch (error) {
      console.error("Error inactivating clerk:", error);
    }

    console.log("Inactivate clerk", id);
  };

  const groupSalesByClerk = (sales) => {
    return sales.reduce((groups, sale) => {
      const { username } = sale.clerk;

      if (!groups[username]) {
        groups[username] = [];
      }
      groups[username].push(sale);
      return groups;
    }, {});
  };

  const groupedSales = groupSalesByClerk(sales);

  const calculateTotals = (data) => {
    return Object.keys(data).map((product) => {
      const totalQuantitySold = data[product].reduce(
        (sum, record) => sum + record.quantity_sold,
        0
      );
      const totalProfit = data[product].reduce(
        (sum, record) => sum + record.profit,
        0
      );
      return {
        name: product.charAt(0).toUpperCase() + product.slice(1), // Capitalizes the product name
        quantitySold: totalQuantitySold,
        profit: totalProfit,
      };
    });
  };

  const result = calculateTotals(groupedSalesProduct);

  const colors = [
    "#4F46E5", // Light Purple
    "#C76D57", // Light Green
    "#ffc658", // Light Orange
    "#a4de6c", // Light Lime
    "#d0ed57", // Light Yellow
    "#8dd1e1", // Light Blue
    "#83a6ed", // Medium Blue
    "#d074cb", // Light Pink
    "#8884d8", // Medium Purple
    "#ff8042", // Orange
    "#ffbb28", // Yellow
    "#00C49F", // Teal
    "#FF8042", // Dark Orange
    "#FFBB28", // Yellow-Orange
    "#FF7F50", // Coral
    "#FF4500", // Orange-Red
    "#FFD700", // Gold
    "#9ACD32", // Yellow-Green
    "#32CD32", // Lime Green
    "#6495ED", // Cornflower Blue
  ];

  const calculateClerkSales = (data) => {
    if (data[0]) {
      return data.map((clerk, index) => {
        const totalQuantitySold = clerk.salesReports.reduce(
          (sum, report) => sum + report.quantity_sold,
          0
        );
        return {
          name: clerk.username,
          value: totalQuantitySold,
          fill: colors[index] || "#000000", // Assign color from the array or default to black
        };
      });
    }
  };

  const clerkSalesData = calculateClerkSales(clerks);
  if (user.role === "Admin" || user.role === "Merchant") {
    return (
      <div
        className={`flex ${
          darkMode ? "dark" : ""
        } bg-background text-text dark:bg-dark-background dark:text-dark-text`}
      >
        {/* Sidebar Component */}
        <Sidebar />

        <main className="p-4 flex-grow transition-all duration-300 ease-in-out">
          <header className="flex justify-between items-center mb-6">
            <motion.h1
              className="text-2xl font-bold"
              initial={{ opacity: 0, x: -50 }}
              animate={{ opacity: 1, x: 0 }}
            >
              {user.role === "Admin" ? user.username : storeAdmin.username}
            </motion.h1>

            <motion.button
              className="add-clerk-btn bg-accent1 text-white px-4 py-2 rounded-md hover:bg-hover dark:bg-dark-accent1 dark:hover:bg-dark-hover"
              whileHover={{ scale: 1.05 }}
              onClick={() => setShowAddClerkPopup(true)}
            >
              <span className="plus-icon mr-2">+</span> Add Clerk
            </motion.button>
          </header>

          {/* Supply Requests Section */}
          <section className="supply-requests mb-8">
            <h2 className="text-xl font-semibold mb-4">Supply Requests</h2>
            <div className="table-responsive overflow-x-auto">
              <table className="min-w-full table-auto">
                <thead className="bg-secondary dark:bg-dark-secondary">
                  <tr>
                    <th>Clerk</th>
                    <th>Product</th>
                    <th>Quantity</th>
                    <th>Status</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                {supplyRequests[0] && (
                  <tbody>
                    {supplyRequests.map((request) => (
                      <motion.tr
                        key={request.id}
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                      >
                        <td>{request.clerk.username}</td>
                        <td>{request.product.product_name}</td>
                        <td>{request.quantity}</td>
                        <td>{request.status}</td>
                        <td>
                          {request.status === "Pending" && (
                            <>
                              <motion.button
                                className="approve-btn bg-primary text-white px-2 py-1 rounded-md hover:bg-hover dark:bg-dark-primary dark:hover:bg-dark-hover"
                                whileHover={{ scale: 1.05 }}
                                onClick={() => handleApproveRequest(request.id)}
                              >
                                Approve
                              </motion.button>
                              <motion.button
                                className="decline-btn bg-accent1 text-white px-2 py-1 rounded-md ml-2 hover:bg-hover dark:bg-dark-accent2 dark:hover:bg-dark-hover"
                                whileHover={{ scale: 1.05 }}
                                onClick={() => handleDeclineRequest(request.id)}
                              >
                                Decline
                              </motion.button>
                            </>
                          )}
                        </td>
                      </motion.tr>
                    ))}
                  </tbody>
                )}
              </table>
            </div>
          </section>

          {/* Products Section */}
          <section className="products mb-8">
            <h2 className="text-xl font-semibold mb-4">Products</h2>
            <div className="table-responsive overflow-x-auto">
              <table className="min-w-full table-auto">
                <thead className="bg-secondary dark:bg-dark-secondary">
                  <tr>
                    <th>Item</th>
                    <th>Paid Status</th>
                    <th>Spoilt</th>
                    <th>Remaining Stock</th>
                    <th>Unit Price</th>
                    <th>Buying Price</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {products.map((product) => (
                    <motion.tr
                      key={product.id}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                    >
                      <td>{product.product_name}</td>
                      <td>
                        {product.payment_status === "paid" ? (
                          "Paid"
                        ) : (
                          <button onClick={() => handleMarkAsPaid(product.id)}>
                            Mark as Paid
                          </button>
                        )}
                      </td>
                      <td>{product.spoilt_items}</td>
                      <td>{product.closing_stock}</td>
                      <td>
                        {editingProductId === product.id ? (
                          <input
                            type="number"
                            value={editedUnitPrice}
                            onChange={(e) => setEditedUnitPrice(e.target.value)}
                          />
                        ) : (
                          product.selling_price
                        )}
                      </td>
                      <td>
                        {editingProductId === product.id ? (
                          <input
                            type="number"
                            value={editedBuyingPrice}
                            onChange={(e) =>
                              setEditedBuyingPrice(e.target.value)
                            }
                          />
                        ) : (
                          product.buying_price
                        )}
                      </td>
                      <td>
                        {editingProductId === product.id ? (
                          <>
                            <button onClick={() => handleSaveClick(product.id)}>
                              Save
                            </button>
                            <button onClick={handleCancelClick}>Cancel</button>
                          </>
                        ) : (
                          <button onClick={() => handleEditClick(product)}>
                            Edit
                          </button>
                        )}
                      </td>
                    </motion.tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          <section className="clerks">
            <h2 className="text-primary text-lg font-semibold">Clerks</h2>
            <div className="overflow-x-auto">
              <table className="min-w-full bg-background text-left border border-border">
                <thead className="bg-secondary">
                  <tr>
                    <th className="px-4 py-2">Name</th>
                    <th className="px-4 py-2">Email</th>
                    <th className="px-4 py-2">Status</th>
                    <th className="px-4 py-2">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {clerks[0] &&
                    clerks.map((clerk) => (
                      <tr
                        key={clerk.id}
                        className="bg-white dark:bg-dark.secondary"
                      >
                        <td className="px-4 py-2 border-b border-border">
                          {clerk.username}
                        </td>
                        <td className="px-4 py-2 border-b border-border">
                          {clerk.email}
                        </td>
                        <td className="px-4 py-2 border-b border-border">
                          {clerk.account_status}
                        </td>
                        <td className="px-4 py-2 border-b border-border">
                          <button
                            className="approve-btn bg-primary text-white px-2 py-1 rounded-md hover:bg-hover dark:bg-dark-primary dark:hover:bg-dark-hover"
                            onClick={() => handleInactivateClerk(clerk.id)}
                          >
                            {clerk.account_status}
                          </button>
                          <button
                            className="decline-btn bg-accent1 text-white px-2 py-1 rounded-md ml-2 hover:bg-hover dark:bg-dark-accent2 dark:hover:bg-dark-hover"
                            onClick={() => handleRemoveClerk(clerk.id)}
                          >
                            Delete
                          </button>
                        </td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>
          </section>

          {Object.keys(groupedSales).map((itemName) => (
            <section key={itemName} className="clerk-sales mt-8">
              <h3 className="text-primary text-lg font-semibold">{itemName}</h3>
              <div className="overflow-x-auto">
                <table className="min-w-full bg-background text-left border border-border">
                  <thead className="bg-secondary">
                    <tr>
                      <th className="px-4 py-2">DATE</th>
                      <th className="px-4 py-2">ITEM</th>
                      <th className="px-4 py-2">QUANTITY SOLD</th>
                      <th className="px-4 py-2">QUANTITY UNSOLD</th>
                      <th className="px-4 py-2">PROFIT</th>
                    </tr>
                  </thead>
                  <tbody>
                    {groupedSales[itemName].map((sale) => (
                      <tr
                        key={sale.id}
                        className="bg-white dark:bg-dark.secondary"
                      >
                        <td className="px-4 py-2 border-b border-border">
                          {new Date(sale.date).toLocaleDateString()}
                        </td>
                        <td className="px-4 py-2 border-b border-border">
                          {sale.product_name}
                        </td>
                        <td className="px-4 py-2 border-b border-border">
                          {sale.quantity_sold}
                        </td>
                        <td className="px-4 py-2 border-b border-border">
                          {sale.quantity_in_hand}
                        </td>
                        <td className="px-4 py-2 border-b border-border">
                          {sale.profit}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>
          ))}

          <section className="performance-reports mt-8">
            <h2 className="text-primary text-lg font-semibold">
              Performance Reports
            </h2>
            {Object.entries(reports).map(([product, data]) => (
              <div key={product} className="product-report mt-4">
                <h3 className="text-secondary text-md font-semibold">
                  {product.charAt(0).toUpperCase() + product.slice(1)} Sales
                  Trends
                </h3>
                <ResponsiveContainer width="100%" height={400}>
                  <LineChart data={data}>
                    <XAxis dataKey="date" />
                    <YAxis yAxisId="left" />
                    <YAxis yAxisId="right" orientation="right" />
                    <CartesianGrid strokeDasharray="3 3" />
                    <Tooltip />
                    <Legend />
                    <Line
                      yAxisId="left"
                      type="monotone"
                      dataKey="quantity_sold"
                      stroke="#4F46E5"
                      name="Quantity Sold"
                    />
                    <Line
                      yAxisId="left"
                      type="monotone"
                      dataKey="quantity_in_hand"
                      stroke={darkMode ? "#1F293" : "#F3F4F6"}
                      name="Quantity in Hand"
                    />
                    <Line
                      yAxisId="right"
                      type="monotone"
                      dataKey="profit"
                      stroke={darkMode ? "#BFAF6C" : "#C76D57"}
                      name="Profit (KSH)"
                    />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            ))}
          </section>

          <section className="product-performance-comparison mt-8">
            <h2 className="text-primary text-lg font-semibold">
              Product Performance Comparison
            </h2>
            <ResponsiveContainer width="100%" height={400}>
              <BarChart data={result}>
                <XAxis dataKey="name" />
                <YAxis yAxisId="left" />
                <YAxis yAxisId="right" orientation="right" />
                <CartesianGrid strokeDasharray="3 3" />
                <Tooltip />
                <Legend />
                <Bar
                  yAxisId="left"
                  dataKey="quantitySold"
                  fill="#4F46E5"
                  name="Quantity Sold"
                />
                <Bar
                  yAxisId="right"
                  dataKey="profit"
                  fill="#1E3A8A"
                  name="Profit (KSH)"
                />
              </BarChart>
            </ResponsiveContainer>
          </section>

          <section className="clerk-performance-comparison mt-8">
            <h2 className="text-primary text-lg font-semibold">
              Clerk Performance Comparison
            </h2>
            <ResponsiveContainer width="100%" height={400}>
              <PieChart>
                <Pie
                  data={clerkSalesData}
                  dataKey="value"
                  nameKey="name"
                  cx="50%"
                  cy="50%"
                  outerRadius={120}
                  label
                />
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </section>
        </main>
        {showProduct && (
          <div className="popup fixed inset-0 bg-gray-800 bg-opacity-75 flex items-center justify-center">
            <div className="popup-content bg-white dark:bg-dark.secondary p-6 rounded-md">
              <h2 className="text-lg font-semibold">Add New Product</h2>
              <input
                className="w-full mt-2 p-2 border border-border rounded-md"
                type="text"
                name="brand_name"
                value={newProduct.brand_name}
                onChange={handleAddProductChange}
                placeholder="Brand Name"
              />
              <input
                className="w-full mt-2 p-2 border border-border rounded-md"
                type="text"
                name="product_name"
                value={newProduct.product_name}
                onChange={handleAddProductChange}
                placeholder="Product Name"
              />
              <input
                className="w-full mt-2 p-2 border border-border rounded-md"
                type="number"
                name="number_of_items"
                value={newProduct.number_of_items}
                onChange={handleAddProductChange}
                placeholder="Number of Items"
              />
              <input
                className="w-full mt-2 p-2 border border-border rounded-md"
                type="number"
                name="buying_price"
                value={newProduct.buying_price}
                onChange={handleAddProductChange}
                placeholder="Buying Price"
              />
              <input
                className="w-full mt-2 p-2 border border-border rounded-md"
                type="number"
                name="selling_price"
                value={newProduct.selling_price}
                onChange={handleAddProductChange}
                placeholder="Selling Price"
              />
              <button
                className="w-full mt-4 bg-primary text-white py-2 rounded-md hover:bg-hover transition duration-300"
                onClick={handleAddProductSubmit}
              >
                Add
              </button>
              <button
                className="w-full mt-2 bg-red-500 text-white py-2 rounded-md hover:bg-red-700 transition duration-300"
                onClick={() => dispatch(showAddProduct(false))}
              >
                Cancel
              </button>
            </div>
          </div>
        )}

        {showAddClerkPopup && (
          <div className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-50">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-lg p-6 max-w-sm w-full">
              <h2 className="text-xl font-semibold mb-4 text-gray-800 dark:text-gray-200">
                Add New Clerk
              </h2>
              <input
                type="text"
                value={newClerkName}
                onChange={(e) => setNewClerkName(e.target.value)}
                placeholder="Enter clerk name"
                className="border border-gray-300 dark:border-gray-600 rounded-md p-2 mb-4 w-full focus:outline-none focus:ring-2 focus:ring-primary dark:focus:ring-accent1"
              />
              <input
                type="email"
                value={newClerkEmail}
                onChange={(e) => setNewClerkEmail(e.target.value)}
                placeholder="Enter clerk email"
                className="border border-gray-300 dark:border-gray-600 rounded-md p-2 mb-4 w-full focus:outline-none focus:ring-2 focus:ring-primary dark:focus:ring-accent1"
              />
              <div className="flex justify-between">
                <button
                  onClick={handleAddClerk}
                  className="bg-primary text-white rounded-md px-4 py-2 hover:bg-hover transition duration-200"
                >
                  Add
                </button>
                <button
                  onClick={() => setShowAddClerkPopup(false)}
                  className="bg-gray-300 text-gray-800 rounded-md px-4 py-2 hover:bg-gray-400 transition duration-200"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }
};

export default AdminPage;
