import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';

const AddAdminForm = ({ onClose }) => {
    const [email, setEmail] = useState('');
    const [storeName, setStoreName] = useState('');
    const [stores, setStores] = useState([]);
    const darkMode = useSelector((state) => state.darkMode.mode);

    useEffect(() => {
        fetch("https://my-duka-back-end.vercel.app/stores")
            .then(res => res.json())
            .then(data => setStores(data));
    }, []);

    const handleSubmit = (e) => {
        e.preventDefault();

        const selectedStoreId = stores.find(store => store.name === storeName)?.id;

        if (!selectedStoreId) {
            alert('Store not found or not selected.');
            return;
        }

        fetch("https://my-duka-back-end.vercel.app/inviteAdmin", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify({ store_id: selectedStoreId, email: email })
        })
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                return response.json();
            })
            .then(() => {
                onClose();
            })
            .catch(error => {
                console.error('There was a problem with the fetch operation:', error);
                alert('Failed to add new admin.');
            });
    };

    return (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
            <div className={`rounded-lg shadow-lg p-6 w-80 ${darkMode ? 'bg-secondary' : 'bg-white'}`}>
                <h2 className={`text-lg font-semibold ${darkMode ? 'text-accent2' : 'text-primary'}`}>Add Admin</h2>
                <form onSubmit={handleSubmit} className="mt-4">
                    <div className="mb-4">
                        <label className={`block text-sm ${darkMode ? 'text-text' : 'text-text'}`}>Email:</label>
                        <input
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required
                            className={`mt-1 block w-full p-2 border rounded-md focus:outline-none focus:ring-2 
                                ${darkMode ? 'border-border dark:border-border focus:ring-dark:primary' : 'border-border focus:ring-primary'}`}
                        />
                    </div>
                    <div className="mb-4">
                        <label className={`block text-sm ${darkMode ? 'text-text' : 'text-text'}`}>Store:</label>
                        <select
                            value={storeName}
                            onChange={(e) => setStoreName(e.target.value)}
                            required
                            className={`mt-1 block w-full p-2 border rounded-md focus:outline-none focus:ring-2 
                                ${darkMode ? 'border-border dark:border-border focus:ring-dark:primary' : 'border-border focus:ring-primary'}`}
                        >
                            <option value="" disabled>Select a store</option>
                            {stores && stores.map((store) => (
                                <option key={store.id}>{store.name}</option>
                            ))}
                        </select>
                    </div>
                    <div className="flex justify-between">
                        <button
                            type="submit"
                            className={`px-4 py-2 rounded-md 
                                ${darkMode ? 'bg-dark:primary hover:bg-dark:primary' : 'bg-primary text-white hover:bg-hover'}`}
                        >
                            Add
                        </button>
                        <button
                            type="button"
                            onClick={onClose}
                            className={`border rounded-md px-4 py-2 
                                ${darkMode ? 'border-border dark:border-border text-text' : 'border-border text-text'} 
                                hover:bg-hover dark:hover:bg-dark:primary`}
                        >
                            Cancel
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default AddAdminForm;
