import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import myImage from "../../assets/images/[CITYPNG.COM]PNG Login Logout White Icon - 800x800.png";
import profileIcon from "../../assets/images/IMG_20240727_142324_284.jpg"; // Profile icon image
import { auth } from "../ChatBot";
import Profile from "../Profile/Profile";
import { useDispatch, useSelector } from "react-redux";
import { switchMode } from "../../features/darkModeSlice";
import { showAddProduct } from "../../features/showAddProductSlice";
import { showAddStore } from "../../features/showAddStoreSlice";
import { motion } from "framer-motion";

const Sidebar = () => {
  const [isSidebarVisible, setIsSidebarVisible] = useState(true);
  const user = useSelector((state) => state.user.user);
  const darkMode = useSelector((state) => state.darkMode.mode);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [showProfile, setShowProfile] = useState(false);

  const handleLogout = () => {
    localStorage.clear("access_token");
    auth.signOut();
    navigate("/");
  };

  const toggleProfile = () => {
    setShowProfile(!showProfile);
  };

  const toggleSidebar = () => {
    setIsSidebarVisible(!isSidebarVisible);
  };

  useEffect(() => {
    const savedMode = localStorage.getItem("darkMode");
    if (savedMode) {
      dispatch(switchMode(JSON.parse(savedMode)));
    }
  }, [dispatch]);

  const toggleDarkMode = () => {
    dispatch(switchMode());
    localStorage.setItem("darkMode", JSON.stringify(!darkMode));
  };

  return (
    <>
      <button
        className={`fixed top-3 right-3 bg-primary text-white rounded p-2 z-50 transition duration-300 hover:bg-hover`}
        onClick={toggleSidebar}
      >
        {isSidebarVisible ? "☰" : "X"}
      </button>

      <motion.div
        className={`fixed top-0 left-0 h-full w-80 p-5 flex flex-col items-center gap-8 transition-transform duration-300 ${
          isSidebarVisible ? "translate-x-0" : "-translate-x-full"
        } ${darkMode ? "bg-dark-secondary text-dark-text" : "bg-primary text-white"}`}
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
      >
        <h2
          className={`cursor-pointer ${darkMode?"text-dark-text":"text-text"}`}
          onClick={() => {
            navigate(user.role === "Merchant" ? "/merchant" : user.role === "Clerk" ? `/clerk/${user.id}` : `/admin/${user.id}`);
          }}
        >
          My Duka
        </h2>
        
        <div className="flex flex-col items-center mb-5">
          <img
            src={user.profilePicture}
            alt="Profile Icon"
            className="w-20 h-20 rounded-full cursor-pointer mb-2"
            onClick={toggleProfile}
          />
          <span className="text-lg">{user.username}</span>
        </div>

        <button
          className="bg-accent1 text-white py-2 px-4 rounded transition duration-200 hover:bg-accent2 w-full"
          onClick={() => {
            navigate(user.role === "Merchant" ? "/merchant" : user.role === "Clerk" ? `/clerk/${user.id}` : `/admin/${user.id}`);
          }}
        >
          Dashboard
        </button>
        
        <button
          className="bg-accent1 text-white py-2 px-4 rounded transition duration-200 hover:bg-accent2 w-full"
          onClick={() => navigate("/chatBot")}
        >
          Messages
        </button>
        
        <button
          onClick={toggleDarkMode}
          className="bg-accent1 text-white py-2 px-4 rounded transition duration-200 hover:bg-accent2 w-full"
        >
          {darkMode ? "Light Mode" : "Dark Mode"}
        </button>
        
        <div className="flex items-center justify-center gap-3">
          <img src={myImage} width={30} alt="logout" />
          <h2
            onClick={handleLogout}
            className={`cursor-pointer mt-2 underline hover:no-underline  ${darkMode?"text-dark-text":"text-text"}`}
          >
            Log Out
          </h2>
        </div>
        
        {user.role === "Admin" && (
          <button
            className="bg-accent1 text-white py-2 px-4 rounded transition duration-200 hover:bg-accent2 w-full"
            onClick={() => dispatch(showAddProduct())}
          >
            <span className="text-lg">+</span> Add Product
          </button>
        )}

        {user.role === "Merchant" && (
          <button
            className="bg-accent1 text-white py-2 px-4 rounded transition duration-200 hover:bg-accent2 w-full"
            onClick={() => dispatch(showAddStore())}
          >
            <span className="text-lg">+</span> Add Store
          </button>
        )}

        {showProfile && <Profile onClose={toggleProfile} />}
      </motion.div>
      
      <div className={`transition-margin duration-300 ${isSidebarVisible ? 'ml-80' : 'ml-0'}`}>
        {/* Main content goes here */}
      </div>
    </>
  );
};

export default Sidebar;
